139	class KernelLeakyRelu {
140	public:
141	    __aicore__ inline KernelLeakyRelu() {}
142	    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y, uint32_t totalLength, uint32_t tileNum, float negativeSlope)
143	    {
144	        this->blockLength = totalLength / AscendC::GetBlockNum();
145	        this->tileNum = tileNum;
146	        this->negativeSlope = static_cast<float>(negativeSlope);
147	        this->tileLength = this->blockLength / tileNum / BUFFER_NUM;
148	
149	        // get start index for current core, core parallel
150	        xGm.SetGlobalBuffer((__gm__ float *)x + this->blockLength * AscendC::GetBlockIdx(), this->blockLength);
151	        yGm.SetGlobalBuffer((__gm__ float *)y + this->blockLength * AscendC::GetBlockIdx(), this->blockLength);
152	        // pipe alloc memory to queue, the unit is Bytes
153	        pipe.InitBuffer(inQueueX, BUFFER_NUM, this->tileLength * sizeof(float));
154	        pipe.InitBuffer(outQueueY, BUFFER_NUM, this->tileLength * sizeof(float));
155	        pipe.InitBuffer(tmpBuffer1, this->tileLength * sizeof(float));
156	        pipe.InitBuffer(tmpBuffer2, this->tileLength * sizeof(float));
157	    }
158	    __aicore__ inline void Process()
159	    {
160	        // loop count need to be doubled, due to double buffer
161	        int32_t loopCount = this->tileNum * BUFFER_NUM;
162	        // tiling strategy, pipeline parallel
163	        for (int32_t i = 0; i < loopCount; i++) {
164	            CopyIn(i);
165	            Compute(i);
166	            CopyOut(i);
167	        }
168	    }
169	
170	private:
171	    __aicore__ inline void CopyIn(int32_t progress)
172	    {
173	        // alloc tensor from queue memory
174	        AscendC::LocalTensor<float> xLocal = inQueueX.AllocTensor<float>();
175	        // copy progress_th tile from global tensor to local tensor
176	        AscendC::DataCopy(xLocal, xGm[progress * this->tileLength], this->tileLength);
177	        // enque input tensors to VECIN queue
178	        inQueueX.EnQue(xLocal);
179	    }
180	    __aicore__ inline void Compute(int32_t progress)
181	    {
182	        // deque input tensors from VECIN queue
183	        AscendC::LocalTensor<float> xLocal = inQueueX.DeQue<float>();
184	        AscendC::LocalTensor<float> yLocal = outQueueY.AllocTensor<float>();
185	        AscendC::LocalTensor<float> tmpTensor1 = tmpBuffer1.Get<float>();
186	        AscendC::LocalTensor<float> tmpTensor2 = tmpBuffer2.Get<float>();
187	        float inputVal = 0.0;
188	        AscendC::Maxs(tmpTensor1, xLocal, inputVal, this->tileLength);
189	        AscendC::Mins(tmpTensor2, xLocal, inputVal, this->tileLength);
190	        AscendC::Muls(tmpTensor2, tmpTensor2, this->negativeSlope, this->tileLength);
191	        AscendC::Add(yLocal, tmpTensor1, tmpTensor2, this->tileLength);
192	        // enque the output tensor to VECOUT queue
193	        outQueueY.EnQue<float>(yLocal);
194	        // free input tensors for reuse
195	        inQueueX.FreeTensor(xLocal);
196	    }
197	    __aicore__ inline void CopyOut(int32_t progress)
198	    {
199	        // deque output tensor from VECOUT queue
200	        AscendC::LocalTensor<float> yLocal = outQueueY.DeQue<float>();
201	        // copy progress_th tile from local tensor to global tensor
202	        AscendC::DataCopy(yGm[progress * this->tileLength], yLocal, this->tileLength);
203	        // free output tensor for reuse
204	        outQueueY.FreeTensor(yLocal);
205	    }
206	
207	private:
208	    AscendC::TPipe pipe;
209	    AscendC::TBuf<AscendC::QuePosition::VECCALC> tmpBuffer1, tmpBuffer2;
210	    // create queues for input, in this case depth is equal to buffer num
211	    AscendC::TQue<AscendC::QuePosition::VECIN, BUFFER_NUM> inQueueX;
212	    // create queue for output, in this case depth is equal to buffer num
213	    AscendC::TQue<AscendC::QuePosition::VECOUT, BUFFER_NUM> outQueueY;
214	    AscendC::GlobalTensor<float> xGm, yGm;
