#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 1;
constexpr uint32_t POOL_K = 2;

class KernelFusedScaleMaxpoolAvgpoolClamp {
public:
    __aicore__ inline KernelFusedScaleMaxpoolAvgpoolClamp() {}
    __aicore__ inline void Init(GM_ADDR x, GM_ADDR y,
                                uint32_t totalChannels, uint32_t depth,
                                uint32_t height, uint32_t width, float scale)
    {
        this->D = depth;
        this->H = height;
        this->W = width;
        this->scale = scale;
        this->Waligned = (W + 7) / 8 * 8;
        this->Dout = D / POOL_K;
        this->Hout = H / POOL_K;
        this->Wout = W / POOL_K;
        this->numBlocks = Dout * Hout * Wout;
        this->spatialSize = D * H * W;

        uint32_t blockNum = AscendC::GetBlockNum();
        uint32_t blockIdx = AscendC::GetBlockIdx();
        uint32_t channelsPerCore = totalChannels / blockNum;
        uint32_t extraChannels = totalChannels % blockNum;

        if (blockIdx < extraChannels) {
            this->myChannels = channelsPerCore + 1;
            this->startChannel = blockIdx * (channelsPerCore + 1);
        } else {
            this->myChannels = channelsPerCore;
            this->startChannel = extraChannels * (channelsPerCore + 1) +
                                 (blockIdx - extraChannels) * channelsPerCore;
        }

        xGm.SetGlobalBuffer((__gm__ float*)x + (uint64_t)startChannel * spatialSize,
                             myChannels * spatialSize);
        yGm.SetGlobalBuffer((__gm__ float*)y + startChannel, myChannels);

        pipe.InitBuffer(inQueue, BUFFER_NUM, 4 * Waligned * sizeof(float));
        pipe.InitBuffer(tmpBuf, 2 * Waligned * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        if (myChannels == 0) return;

        for (uint32_t ch = 0; ch < myChannels; ch++) {
            float blockSum = 0.0f;
            uint32_t chOffset = ch * spatialSize;

            for (uint32_t d = 0; d < Dout; d++) {
                for (uint32_t h = 0; h < Hout; h++) {
                    CopyIn(chOffset, d, h);
                    blockSum += Compute();
                }
            }

            float avg = blockSum / static_cast<float>(numBlocks);
            if (avg < 0.0f) avg = 0.0f;
            if (avg > 1.0f) avg = 1.0f;
            yGm.SetValue(ch, avg);
        }
    }

private:
    __aicore__ inline void CopyIn(uint32_t chOffset, uint32_t d, uint32_t h)
    {
        AscendC::LocalTensor<float> inLocal = inQueue.AllocTensor<float>();
        uint32_t d0 = d * POOL_K;
        uint32_t h0 = h * POOL_K;
        uint32_t baseOff = chOffset + d0 * H * W;
        AscendC::DataCopy(inLocal[0],                  xGm[baseOff + h0 * W],       Waligned);
        AscendC::DataCopy(inLocal[Waligned],           xGm[baseOff + (h0 + 1) * W], Waligned);
        AscendC::DataCopy(inLocal[2 * Waligned],       xGm[baseOff + H * W + h0 * W],       Waligned);
        AscendC::DataCopy(inLocal[3 * Waligned],       xGm[baseOff + H * W + (h0 + 1) * W], Waligned);
        inQueue.EnQue(inLocal);
    }

    __aicore__ inline float Compute()
    {
        AscendC::LocalTensor<float> inLocal = inQueue.DeQue<float>();
        AscendC::LocalTensor<float> tmp = tmpBuf.Get<float>();

        AscendC::Muls(inLocal[0],              inLocal[0],              scale, Waligned);
        AscendC::Muls(inLocal[Waligned],       inLocal[Waligned],       scale, Waligned);
        AscendC::Muls(inLocal[2 * Waligned],   inLocal[2 * Waligned],   scale, Waligned);
        AscendC::Muls(inLocal[3 * Waligned],   inLocal[3 * Waligned],   scale, Waligned);

        AscendC::Max(tmp[0],        inLocal[0],            inLocal[Waligned],       Waligned);
        AscendC::Max(tmp[Waligned], inLocal[2 * Waligned], inLocal[3 * Waligned],   Waligned);
        AscendC::Max(tmp[0],        tmp[0],                tmp[Waligned],           Waligned);

        float pairSum = 0.0f;
        for (uint32_t w = 0; w < Wout; w++) {
            float v0 = tmp.GetValue(2 * w);
            float v1 = tmp.GetValue(2 * w + 1);
            pairSum += (v0 > v1) ? v0 : v1;
        }

        inQueue.FreeTensor(inLocal);
        return pairSum;
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN, BUFFER_NUM> inQueue;
    AscendC::TBuf<AscendC::TPosition::VECCALC> tmpBuf;
    AscendC::GlobalTensor<float> xGm;
    AscendC::GlobalTensor<float> yGm;

    uint32_t D, H, W, Waligned;
    uint32_t Dout, Hout, Wout;
    uint32_t numBlocks;
    uint32_t spatialSize;
    uint32_t myChannels;
    uint32_t startChannel;
    float scale;
};

extern "C" __global__ __aicore__ void conv_transpose3d_multiply_max_global_avg_pool_clamp_custom(
    GM_ADDR x, GM_ADDR y, GM_ADDR workspace, GM_ADDR tiling)
{
    GET_TILING_DATA(tiling_data, tiling);
